namespace ghidra.app.plugin.core.equate;

using ghidra.docking.settings;
using ghidra.program.model.listing;
using ghidra.program.model.scalar;

public class ConvertToUnsignedHexAction : AbstractConvertAction {
	public static string ACTION_NAME = "Convert To Unsigned Hex";

	public ConvertToUnsignedHexAction(EquatePlugin plugin) : base(plugin, ACTION_NAME, false)
    {
	}

	/* @Override */
	protected string getMenuName(Program program, Scalar scalar, bool isData) {
		return getStandardLengthString("Unsigned Hex:") + convertToString(program, scalar, isData);
	}

	/* @Override */
	protected string convertToString(Program program, Scalar scalar, bool isData) {
		string valueStr = Long.toHexString(scalar.getUnsignedValue()).toUpperCase();
		if (isData) {
			// Data relies on data format settings which uses "h" suffix
			return valueStr + "h";
		}
		// Instructions rely on equate which uses 0x prefix (consistent with default scalar formatting)
		return "0x" + valueStr;
	}

	/* @Override */
	protected int getFormatChoice() {
		return FormatSettingsDefinition.HEX;
	}

}
